import numpy as np, pickle
G=np.load('G.npy')
def groups(M,thr=0.85):
    n=M.shape[0]; lab=-np.ones(n,int); reps=[]
    for i in range(n):
        best=-1;bs=0
        for k,r in enumerate(reps):
            m=(M[i]>=0)&(M[r]>=0)
            ag=(M[i]==M[r])[m].mean() if m.sum() else 0
            if ag>bs: bs=ag;best=k
        if bs>=thr: lab[i]=best
        else: reps.append(i); lab[i]=len(reps)-1
    return lab
out={}
np.set_printoptions(linewidth=250)
for s in range(4):
    ra=groups(G[s]); rb=groups(G[s].T)
    na,nb=ra.max()+1,rb.max()+1
    T=-np.ones((na,nb),int); pur=np.zeros((na,nb)); tot=0;agree=0
    for i in range(na):
        for j in range(nb):
            v=G[s][np.ix_(ra==i,rb==j)]; v=v[v>=0]
            if len(v):
                c=np.bincount(v); T[i,j]=c.argmax(); agree+=c.max(); tot+=len(v)
    out[s]=(ra,rb,T)
    print('skill',s,'a groups',na,'b groups',nb,'agreement',round(agree/tot,4))
    print('a->',ra.tolist()); print('b->',rb.tolist())
    for row in T: print(' '.join('%2s'%('.' if x<0 else x) for x in row))
pickle.dump(out,open('cond.pkl','wb'))

