import numpy as np, pickle
G=np.load('G.npy'); C=pickle.load(open('codes.pkl','rb'))
print({n:SHAPES[n] for n in NAMES})
# skill 3 tables read from the sorted grid
yg={0:[11,10,0],1:[14,17],2:[5,31],3:[15,23],4:[7,29,4],5:[16,21],6:[6],7:[9,27,20],8:[18,2,25,8,3,28],10:[30],11:[1,24,26],12:[22,13,19],13:[12]}
y3=np.zeros(32,int)
for k,v in yg.items():
    for b in v: y3[b]=k
V3=y3>>1
tl={15:(0,7),22:(1,7),21:(1,7),8:(3,7),10:(4,6),4:(4,6),16:(4,6),14:(4,6),2:(4,6),19:(6,5),11:(5,5),23:(7,5),5:(7,5),12:(7,5),31:(7,5),
    3:(10,3),24:(10,3),20:(10,3),30:(10,3),25:(10,3),9:(10,3),6:(10,3),26:(10,3),29:(10,3),28:(7,4),17:(7,4),18:(12,2),13:(12,2),0:(13,2),27:(13,1),7:(13,7),1:(14,6)}
tau=np.array([tl[a][0] for a in range(32)]); L3=np.array([tl[a][1] for a in range(32)])
pred3=np.where(y3[None,:]>=tau[:,None],L3[:,None],V3[None,:])
m=G[3]>=0; bad=np.argwhere((pred3!=G[3])&m)
print('skill3 misses',[(int(a),int(b),int(G[3,a,b])) for a,b in bad])
beta=16.0; W1=np.zeros((48,68)); b1=np.zeros(48); W2=np.zeros((48,48)); b2=np.zeros(48); W3=np.zeros((63,48)); b3=np.zeros(63)
n1=[0]; n2=[0]
def l1(A=None,B=None,skill=0,on=0.0,off=-100.0,bias=0.0):
    i=n1[0]; n1[0]+=1
    if A is not None: W1[i,:32]=A
    if B is not None: W1[i,32:64]=B
    W1[i,64:68]=off; W1[i,64+skill]=on; b1[i]=bias
    return i
def l2(terms,bias=0.0):
    i=n2[0]; n2[0]+=1
    for k,v in terms.items(): W2[i,k]+=v
    b2[i]=bias
    return i
def bit(x,i): return ((x>>i)&1).astype(float)
ON=[l1(skill=s,on=20.0,off=-20.0) for s in range(4)]
O2=[l2({ON[s]:1.0}) for s in range(4)]   # 20 when the skill is on, 0 otherwise
frac=lambda s,c:{ON[s]:c/20.0}
Z={}
# skill 0: OR of 4-bit codes
t={}
for i in range(4):
    p,q=bit(C['p0'],i),bit(C['q0'],i)
    a=l1(beta*p,beta*q,0); c=l1(beta*p,beta*q,0,bias=-beta)
    t[a]=2**i/beta; t[c]=-2**i/beta
t.update(frac(0,40.0)); h=l2(t,-20.0); Z[0]={h:1.0,O2[0]:-1.0}
# skill 1: discrete logs add, wrap at 16
lg={pow(3,k,17):k for k in range(16)}
lu=np.array([lg[int(x)] for x in C['u1']],float); lv=np.array([lg[int(x)] for x in C['v1']],float)
T=l1(lu,lv,1,on=40.0)
h=l2({T:1.0},-20.0); s15=l2({T:beta},-beta*55); s16=l2({T:beta},-beta*56)
Z[1]={h:1.0,O2[1]:-1.0,s15:-16/beta,s16:16/beta}
# skill 2: multiply mod 16 as a sum of shifted products, wrap at 16,32,48
P={}
for j in range(4):
    pt=(C['p2']%(2**(4-j))).astype(float); qj=bit(C['q2'],j)
    n=l1(beta*pt,beta*16*qj,2,off=-400.0,bias=-beta*16)
    P[n]=2**j/beta
t=dict(P); t.update(frac(2,40.0)); h=l2(t,-20.0); Z[2]={h:1.0,O2[2]:-1.0}
for th,sg in [(15,-1),(16,1),(31,-1),(32,1),(47,-1),(48,1)]:
    t={k:beta*v for k,v in P.items()}; t.update(frac(2,beta*60.0))
    s=l2(t,-beta*(60+th)); Z[2][s]=sg*16/beta
# skill 3: L(a) if y(b)>=tau(a), otherwise V(b)
c1=l1(-beta*tau.astype(float),beta*y3.astype(float),3,off=-400.0,bias=beta)
c2=l1(-beta*tau.astype(float),beta*y3.astype(float),3,off=-400.0)
LL=l1(L3.astype(float),None,3,on=40.0); VV=l1(None,V3.astype(float),3,on=40.0)
o1=l2({LL:beta,c1:16.0,c2:-16.0},-beta*56)
o2=l2({VV:beta,c1:-16.0,c2:16.0},-beta*40)
Z[3]={o1:1/beta,o2:1/beta}
# outputs: score(c)=g*(2*r*z-r*r) on each skill, unused classes pushed down
g=3.0
r={0:{c:c for c in range(16)},1:{c:lg[c+1] for c in range(16)},2:{c:c for c in range(16)},3:{c:c for c in range(8)}}
for s in range(4):
    for c in range(63):
        if c in r[s]:
            for k,v in Z[s].items(): W3[c,k]+=g*2*r[s][c]*v
            W3[c,O2[s]]+=-g*r[s][c]**2/20.0
        else:
            W3[c,O2[s]]+=-400.0/20.0
print('l1 used',n1[0],'l2 used',n2[0])
silu=lambda x:x/(1+np.exp(np.clip(-x,-500,500)))
def fwd(s,a,b):
    x=np.zeros(68); x[a]=1; x[32+b]=1; x[64+s]=1
    return W3@silu(W2@silu(W1@x+b1)+b2)+b3
full={0:C['p0'][:,None]|C['q0'][None,:],1:(C['u1'][:,None]*C['v1'][None,:]%17)-1,2:C['p2'][:,None]*C['q2'][None,:]%16,3:pred3}
for s in range(4):
    ok=np.mean([fwd(s,a,b).argmax()==full[s][a,b] for a in range(32) for b in range(32)])
    k=G[s]>=0; tr=np.mean([fwd(s,a,b).argmax()==G[s,a,b] for a in range(32) for b in range(32) if k[a,b]])
    print('skill',s,'agrees with rule on all pairs',ok,'train acc',round(float(tr),4))
for n,x in [('l1.weight',W1),('l1.bias',b1),('l2.weight',W2),('l2.bias',b2),('l3.weight',W3),('l3.bias',b3)]:
    assert x.shape==tuple(SHAPES[n]); save_edit(n,x)
np.savez('hand.npz',W1=W1,b1=b1,W2=W2,b2=b2,W3=W3,b3=b3)
